INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 10, 0.5, 0, 11, 101711, "えへへ、言葉にできないくらい\nうれしいさ～！　この気持ちを\nみんなに伝えるには……\n歌って踊るしかないさー！", 0, 14314073, 1, 14314);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", "", "", "", 91, 0, "", "", 14314074, "", 14314);
