INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 10, 0.5, 0, 11, 103011, "そうデス！\nクウカのために、\nショーグンも手伝ってくれたデスよ！\nみんなで甘いケーキを食べまショウ！", 0, 27814083, 1, 27814);
