INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (0, 0, "", "", 21, "vo_wac_30314", "vo_wac_30314_005", "", 30314089, "", 30314);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 10, 0.5, 0, 11, 105911, "わかっております、シェフィさま。\nそれでも……お二人は、あなたを\n大切に想っているのです。\nもちろん、わたくしと主さまも。", 0, 30314090, 1, 30314);
INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES ("", "", "", "", 91, 0, "", "", 30314091, "", 30314);
