INSERT INTO `v1_bb6dc24c3d4337f2484726655a75e3743e294ce7d91efc9ce1c31beba9a5035d` VALUES (1, 10, 0.5, 0, 11, 101211, "ハッピー☆バースデー☆ハツネちゃん！\nおっきなケーキまでもらっちゃって、\n最高の誕生日だよ～きらーんっ☆", 0, 31314058, 1, 31314);
